const { error } = require('console');
const fs = require('fs-extra');
const path = require('path');

var _robloxPathDict;
var _options;

var luaConfigs = {}


function trimKey(key) {
    // remove file extension from key if have
    return key.replace(/\.[^.]+$/, '');
}


function tryParseDefine(filePath, key, config) {

    var rbxPath = _robloxPathDict.getRbxPath(filePath)

    // if file path end with '.lua', or '.json'

    if (filePath.endsWith('.lua') || filePath.endsWith('.json')) {
        luaConfigs[rbxPath] = {
            FilePath: filePath,
            Name: trimKey(key),
            Context: config.Context
        }
    }
}


function gen(filePath) {

    // get file folder
    const fileFolder = path.dirname(filePath);

    function handler(func, key, value) {
        value.ConfigFolder = fileFolder
        var filePath = path.join(fileFolder, key)
        if (value.IsFolder) {
            var newValue = { ...value };  // 深拷贝 value 对象
            newValue.IsFolder = false
            // loop folder
            const folderContent = fs.readdirSync(filePath);
            for (const file of folderContent) {
                // if contains 'InternalHost' or 'HostBuilderContext'

                key = file

                var newPath = path.join(filePath, file)

                func(newPath, key, newValue)
            }

        } else {

            func(filePath, key, value)
        }
    }

    const content = JSON.parse(fs.readFileSync(filePath, 'utf8'));
    for (const [key, value] of Object.entries(content)) {

        handler(tryParseDefine, key, value)

    }
}



// 尝试生成路径, 如果有变更, 返回true
function tryGen(filePath) {

    var changed = false

    // 如果filePath 是文件夹，则检查是否包含'services.json'
    if (fs.existsSync(filePath) && filePath.endsWith('configs.json')) {
        gen(filePath);
        changed = true
    }

    return changed
}

function findAndGenSubfolders(basePath) {
    if (_options.isIgnoreFolder && _options.isIgnoreFolder(path.resolve(basePath))) return
    var changed = false
    if (!fs.existsSync(basePath)) {
        // if parent exits ,try gen
        const parentPath = path.dirname(basePath);
        if (fs.existsSync(parentPath)) {
            return findAndGenSubfolders(parentPath);
        }
        return false
    }
    if (fs.lstatSync(basePath).isDirectory()) {

        for (const item of fs.readdirSync(basePath, { withFileTypes: true })) {

            const fullPath = path.join(basePath, item.name);
            changed |= findAndGenSubfolders(fullPath);
        }
    } else {

        changed |= tryGen(basePath)
    }
    return changed
}

module.exports = {
    Init: function (options) {
        _options = options
        _robloxPathDict = options.robloxPathDict;
        // assert _robloxPathDict is not null
        if (!_robloxPathDict) {
            throw new Error('robloxPathDict is not null')
        }
    },

    TryGen: function (paths) {
        var changed = false
        for (const basePath of paths) {
            changed |= findAndGenSubfolders(basePath);
        }
        return changed
    },
    TryGenOnUpdate: function (events) {
        var changed = false

        for (var key in events) {
            basePath = path.dirname(key);
            if (fs.existsSync(basePath)) {
                changed |= findAndGenSubfolders(basePath)
            }
        }

        return changed
    },
    GetLuaConfigs: function () {
        return luaConfigs
    }

}